  1→/**
  2→ * Pi Model & Provider Discovery (from SDK)
  3→ *
  4→ * Separated from models.ts because @mariozechner/pi-ai transitively pulls in
  5→ * @aws-sdk/client-bedrock-runtime → @smithy/node-http-handler → Node.js `stream`,
  6→ * which breaks the Vite renderer build (browser context, no Node.js modules).
  7→ *
  8→ * This file should ONLY be imported from:
  9→ *   - Main process code (Electron main, IPC handlers)
 10→ *   - Server-side code (build scripts, CLI)
 11→ *   - Registration calls (e.g., registerPiModelResolver)
 12→ *
 13→ * NEVER import this file from renderer components or from files that the renderer imports.
 14→ */
 15→
 16→import { getProviders, getModels } from '@mariozechner/pi-ai';
 17→import type { KnownProvider, Model, Api } from '@mariozechner/pi-ai';
 18→import type { ModelDefinition } from './models.ts';
 19→
 20→// ============================================
 21→// PI MODEL DISCOVERY
 22→// ============================================
 23→
 24→/**
 25→ * Convert a Pi SDK Model to our ModelDefinition format.
 26→ */
 27→function piModelToDefinition(m: Model<Api>): ModelDefinition {
 28→  const lastPart = m.name.split(/[\s-]/).pop() ?? m.name;
 29→  const shortName = m.name.length > 20 ? lastPart : m.name;
 30→
 31→  return {
 32→    id: `pi/${m.id}`,
 33→    name: m.name,
 34→    shortName,
 35→    description: `${m.provider} model via Orcha Agents Backend`,
 36→    provider: 'pi',
 37→    contextWindow: m.contextWindow,
 38→    supportsThinking: m.reasoning,
 39→  };
 40→}
 41→
 42→// ============================================
 43→// CUSTOM ZAI MODELS (not yet in Pi SDK)
 44→// ============================================
 45→
 46→/**
 47→ * ZAI models that are available via the z.ai API but not yet shipped
 48→ * in the Pi SDK's static catalog. These are appended to the SDK list
 49→ * in getPiModelsForAuthProvider() and automatically de-duplicated —
 50→ * once the SDK includes them natively, these entries are ignored.
 51→ */
 52→const ZAI_CUSTOM_MODELS: ModelDefinition[] = [
 53→  {
 54→    id: 'pi/glm-5.1',
 55→    name: 'GLM-5.1',
 56→    shortName: 'GLM-5.1',
 57→    description: 'zai model via Orcha Agents Backend',
 58→    provider: 'pi',
 59→    contextWindow: 204800,
 60→    supportsThinking: true,
 61→  },
 62→  {
 63→    id: 'pi/glm-5v-turbo',
 64→    name: 'GLM-5V-Turbo',
 65→    shortName: 'GLM-5V-Turbo',
 66→    description: 'zai model via Orcha Agents Backend',
 67→    provider: 'pi',
 68→    contextWindow: 202752,
 69→    supportsThinking: true,
 70→  },
 71→];
 72→
 73→/**
 74→ * Get the custom ZAI models list (for use in model refresh merging).
 75→ */
 76→export function getZaiCustomModels(): ModelDefinition[] {
 77→  return ZAI_CUSTOM_MODELS;
 78→}
 79→
 80→/**
 81→ * Models to EXCLUDE from the Pi model list.
 82→ * Temporary workaround for models that are broken in the current Pi SDK version.
 83→ * e.g., gemini-1.5-flash fails with "not found for API version v1beta"
 84→ */
 85→const PI_EXCLUDED_MODELS: Set<string> = new Set([
 86→  // Unsupported 1.5 models
 87→  'gemini-1.5-flash',
 88→  'gemini-1.5-flash-8b',
 89→  'gemini-1.5-pro',
 90→
 91→  // Unsupported 2.0 models
 92→  'gemini-2.0-flash',
 93→  'gemini-2.0-flash-lite',
 94→
 95→  // Stale alias exposed by some SDK catalogs; fails at runtime in OpenAI API-key flow
 96→  'codex-mini-latest',
 97→]);
 98→
 99→/**
100→ * Prefixes to EXCLUDE from the Pi model list.
101→ * Keep this list narrow and intentional.
102→ */
103→const PI_EXCLUDED_MODEL_PREFIXES: string[] = [
104→  // Requested cleanup: hide legacy GPT-4 family variants (gpt-4, gpt-4.1, gpt-4o, ...)
105→  'gpt-4',
106→];
107→
108→function isExcludedPiModel(modelId: string): boolean {
109→  if (PI_EXCLUDED_MODELS.has(modelId)) return true;
110→  return PI_EXCLUDED_MODEL_PREFIXES.some(prefix => modelId.startsWith(prefix));
111→}
112→
113→/**
114→ * Check if a Bedrock model ID is a bare Claude model without a region prefix.
115→ * Bare IDs like `anthropic.claude-opus-4-6-v1` are rejected by Bedrock which
116→ * requires inference profile IDs with a region prefix (`us.`, `eu.`, `global.`).
117→ * The Pi SDK catalog includes proper regional variants, so filtering bare models
118→ * doesn't remove any usable entries.
119→ */
120→function isBareBedrockClaudeModel(modelId: string): boolean {
121→  return modelId.startsWith('anthropic.claude-');
122→}
123→
124→/**
125→ * Get Pi models for a specific auth provider directly from the Pi SDK.
126→ */
127→export function getPiModelsForAuthProvider(piAuthProvider: string): ModelDefinition[] {
128→  let result: ModelDefinition[] = [];
129→
130→  try {
131→    const models = getModels(piAuthProvider as KnownProvider);
132→    if (models.length > 0) {
133→      result = models
134→        .filter(m => !isExcludedPiModel(m.id))
135→        // Bedrock: exclude bare Claude models without region prefix — they're
136→        // always rejected by Bedrock which requires inference profiles (us.*/eu.*/global.*).
137→        // Regional variants from the same catalog are kept.
138→        .filter(m => piAuthProvider !== 'amazon-bedrock' || !isBareBedrockClaudeModel(m.id))
139→        .map(piModelToDefinition);
140→    }
141→  } catch {
142→    // Provider not recognized by SDK — fall through
143→  }
144→
145→  // Append custom ZAI models not yet in the Pi SDK (auto-deduplicates)
146→  if (piAuthProvider === 'zai') {
147→    const sdkIds = new Set(result.map(m => m.id));
148→    for (const custom of ZAI_CUSTOM_MODELS) {
149→      if (!sdkIds.has(custom.id)) {
150→        result.push(custom);
151→      }
152→    }
153→  }
154→
155→  return result;
156→}
157→
158→/**
159→ * Get all Pi models across all providers from the SDK.
160→ */
161→export function getAllPiModels(): ModelDefinition[] {
162→  const allModels: ModelDefinition[] = [];
163→  for (const provider of getProviders()) {
164→    try {
165→      const models = getModels(provider);
166→      allModels.push(...models
167→        .filter(m => !isExcludedPiModel(m.id))
168→        .map(piModelToDefinition)
169→      );
170→    } catch {
171→      // Skip providers that fail
172→    }
173→  }
174→  return allModels;
175→}
