239→/**
240→ * Extract all error messages from an error object, including nested causes.
241→ */
242→function extractErrorMessages(error: unknown): string {
243→  const messages: string[] = [];
244→
245→  if (error instanceof Error) {
246→    messages.push(error.message);
247→
248→    // Check for nested cause (ES2022 Error.cause)
249→    if ('cause' in error && error.cause) {
250→      messages.push(extractErrorMessages(error.cause));
251→    }
252→
253→    // Check for stdout/stderr (common in subprocess errors)
254→    const anyError = error as unknown as Record<string, unknown>;
255→    if (typeof anyError.stdout === 'string') messages.push(anyError.stdout);
256→    if (typeof anyError.stderr === 'string') messages.push(anyError.stderr);
257→    if (typeof anyError.output === 'string') messages.push(anyError.output);
258→  } else {
259→    messages.push(String(error));
260→  }
261→
262→  return messages.join(' ');
263→}
