265→const HTML_DOC_HINTS = ['<html', '<!doctype html', '<head', '<body', '<title', '<h1'] as const;
266→const HTML_PROXY_HINTS = [
267→  'cloudflare',
268→  'cf-ray',
269→  'captcha',
270→  'security check',
271→  'access denied',
272→  'attention required',
273→  'web application firewall',
274→  'waf',
275→  'proxy authentication required',
276→  'sucuri',
277→  'imperva',
278→  'akamai',
279→] as const;
280→const HTML_STATUS_PATTERN = /\b(400|401|403|407|408|409|429|500|502|503|504)\b/;
281→
282→function looksLikeHtmlPayload(textLower: string): boolean {
283→  if (textLower.includes('<!doctype html') || textLower.includes('<html')) {
284→    return true;
285→  }
286→
287→  let hintCount = 0;
288→  for (const hint of HTML_DOC_HINTS) {
289→    if (textLower.includes(hint)) hintCount++;
290→  }
291→
292→  return hintCount >= 3;
293→}
294→
295→function hasHtmlErrorPageSignals(textLower: string): boolean {
296→  const hasKnownHttpTitle =
297→    textLower.includes('bad request') ||
298→    textLower.includes('unauthorized') ||
299→    textLower.includes('forbidden') ||
300→    textLower.includes('service unavailable') ||
301→    textLower.includes('bad gateway') ||
302→    textLower.includes('gateway timeout') ||
303→    textLower.includes('proxy authentication required');
304→
305→  return HTML_STATUS_PATTERN.test(textLower) && hasKnownHttpTitle;
306→}
307→
308→function isLikelyProxyInterception(textLower: string): boolean {
309→  if (textLower.includes('unexpected html error page') || textLower.includes('network proxy')) {
310→    return true;
311→  }
312→
313→  if (!looksLikeHtmlPayload(textLower)) {
314→    return false;
315→  }
316→
317→  if (HTML_PROXY_HINTS.some((hint) => textLower.includes(hint))) {
318→    return true;
319→  }
320→
321→  return hasHtmlErrorPageSignals(textLower);
322→}
323→
324→function buildProxyErrorMessage(errorMessage: string, fullErrorText: string): string {
325→  const lowerErrorMessage = errorMessage.toLowerCase();
326→  if (!looksLikeHtmlPayload(lowerErrorMessage)) {
327→    // Interceptor-produced proxy messages are already user-safe and actionable.
328→    return errorMessage;
329→  }
330→
331→  const details: string[] = [];
332→  const statusMatch = fullErrorText.match(HTML_STATUS_PATTERN);
333→  if (statusMatch?.[1]) {
334→    details.push(`HTTP ${statusMatch[1]}`);
335→  }
336→  if (fullErrorText.toLowerCase().includes('cloudflare')) {
337→    details.push('Cloudflare');
338→  }
339→
340→  const suffix = details.length > 0 ? ` (${details.join(', ')})` : '';
341→  return `Received an unexpected HTML error page${suffix} instead of a JSON API response. This is usually caused by a proxy, firewall, or captive portal intercepting the request. Check your proxy settings in Settings > Network.`;
342→}
