344→/**
345→ * Parse an error and return a typed AgentError with user-friendly info
346→ */
347→export function parseError(
348→  error: unknown,
349→  providerContext?: { providerType?: string; piAuthProvider?: string },
350→): AgentError {
351→  // Extract all error messages including nested causes and subprocess output
352→  const fullErrorText = extractErrorMessages(error);
353→  const errorMessage = error instanceof Error ? error.message : String(error);
354→  const lowerMessage = fullErrorText.toLowerCase();
355→
356→  // Detect error type from message/status
357→  let code: ErrorCode = 'unknown_error';
358→
359→  // Check for OpenRouter data policy errors first (these contain "no endpoints" which could confuse other checks)
360→  if (lowerMessage.includes('data policy') || lowerMessage.includes('privacy')) {
361→    code = 'data_policy_error';
362→  // Check for model-specific errors (OpenRouter, etc.)
363→  // Tool support errors must be checked BEFORE model errors since tool errors often contain "model"
364→  } else if (
365→    lowerMessage.includes('no endpoints found that support tool use') ||
366→    lowerMessage.includes('does not support tool') ||
367→    lowerMessage.includes('tool_use is not supported') ||
368→    lowerMessage.includes('function calling not available') ||
369→    lowerMessage.includes('tools are not supported') ||
370→    lowerMessage.includes('doesn\'t support tool') ||
371→    lowerMessage.includes('tool use is not supported') ||
372→    (lowerMessage.includes('invalid_request_error') && lowerMessage.includes('tool')) ||
373→    // Generic pattern: "tool" + "not" + "support" anywhere in message
374→    (lowerMessage.includes('tool') && lowerMessage.includes('not') && lowerMessage.includes('support'))
375→  ) {
376→    code = 'model_no_tool_support';
377→  } else if (lowerMessage.includes('is not a valid model') || lowerMessage.includes('model not found') || lowerMessage.includes('invalid model') || lowerMessage.includes('model identifier is invalid')) {
378→    code = 'invalid_model';
379→  // HTML-intercepted responses (proxy/firewall/captive portal).
380→  // Must be checked BEFORE status codes: a 502 Cloudflare page or 401 proxy login
381→  // page would otherwise be misclassified as service_error or invalid_api_key.
382→  } else if (isLikelyProxyInterception(lowerMessage)) {
383→    code = 'proxy_error';
384→  // Check for specific HTTP status codes or patterns
385→  } else if (lowerMessage.includes('402') || lowerMessage.includes('payment required')) {
386→    code = 'billing_error';
387→  } else if (lowerMessage.includes('401') || lowerMessage.includes('unauthorized') || lowerMessage.includes('invalid api key') || lowerMessage.includes('invalid x-api-key') || lowerMessage.includes('authentication failed') || lowerMessage.includes('token is expired') || lowerMessage.includes('token expired')) {
388→    // Distinguish between API key and OAuth errors
389→    if (lowerMessage.includes('oauth') || lowerMessage.includes('token') || lowerMessage.includes('session')) {
390→      code = 'expired_oauth_token';
391→    } else {
392→      code = 'invalid_api_key';
393→    }
394→  } else if (lowerMessage.includes('429') || lowerMessage.includes('rate limit') || lowerMessage.includes('too many requests')) {
395→    code = 'rate_limited';
396→  } else if (lowerMessage.includes('500') || lowerMessage.includes('502') || lowerMessage.includes('503') || lowerMessage.includes('504') || lowerMessage.includes('internal server error') || lowerMessage.includes('service unavailable')) {
397→    code = 'service_error';
398→  } else if (lowerMessage.includes('network') || lowerMessage.includes('econnrefused') || lowerMessage.includes('enotfound') || lowerMessage.includes('fetch failed') || lowerMessage.includes('connection')) {
399→    code = 'network_error';
400→  } else if (lowerMessage.includes('mcp') && (lowerMessage.includes('auth') || lowerMessage.includes('401'))) {
401→    code = 'mcp_auth_required';
402→  } else if (
403→    lowerMessage.includes('image') &&
404→    (lowerMessage.includes('dimension') || lowerMessage.includes('8000') || lowerMessage.includes('5mb')) &&
405→    (lowerMessage.includes('exceed') || lowerMessage.includes('too large'))
406→  ) {
407→    code = 'image_too_large';
408→  } else if (lowerMessage.includes('exited with code') || lowerMessage.includes('process exited')) {
409→    // SDK subprocess crashed - likely auth/setup issue
410→    // Check if the error contains more specific info
411→    if (lowerMessage.includes('api') || lowerMessage.includes('key') || lowerMessage.includes('credential')) {
412→      code = 'invalid_api_key';
413→    } else {
414→      code = 'service_error';
415→    }
416→  }
417→
418→  const definition = ERROR_DEFINITIONS[code];
419→
420→  // Resolve provider info from context
421→  const providerInfo = providerContext
422→    ? getProviderMetadata(
423→        providerContext.providerType ?? 'anthropic',
424→        providerContext.piAuthProvider,
425→      ) ?? undefined
426→    : undefined;
427→
428→  // For proxy_error, prefer safe user-facing text over raw HTML payloads.
429→  if (code === 'proxy_error') {
430→    return {
431→      code,
432→      ...definition,
433→      message: buildProxyErrorMessage(errorMessage, fullErrorText),
434→      originalError: errorMessage,
435→      providerInfo,
436→    };
437→  }
438→
439→  // For model_no_tool_support errors, try to extract the model name for a more helpful message
440→  if (code === 'model_no_tool_support') {
441→    // Try to extract model name from various error message formats
442→    // Common patterns: "model: xxx", "model 'xxx'", "model \"xxx\"", "model xxx does not"
443→    const modelMatch = fullErrorText.match(/model[:\s]+["']?([a-zA-Z0-9\-_/:.]+)["']?/i) ||
444→                       fullErrorText.match(/["']([a-zA-Z0-9\-_/:.]+)["']\s+does not support/i);
445→    if (modelMatch?.[1]) {
446→      return {
447→        code,
448→        ...definition,
449→        message: `Model "${modelMatch[1]}" does not support tool/function calling, which is required for Craft Agent. Please choose a different model with tool support in Settings.`,
450→        originalError: errorMessage,
451→        providerInfo,
452→      };
453→    }
454→  }
455→
456→  return {
457→    code,
458→    ...definition,
459→    originalError: errorMessage,
460→    providerInfo,
461→  };
462→}
