464→/**
465→ * Check if an error is a billing/auth error that blocks usage
466→ */
467→export function isBillingError(error: AgentError): boolean {
468→  return error.code === 'billing_error' || error.code === 'invalid_api_key' || error.code === 'expired_oauth_token';
469→}
470→
471→/**
472→ * Check if an error can be automatically retried
473→ */
474→export function canAutoRetry(error: AgentError): boolean {
475→  return error.canRetry && error.retryDelayMs !== undefined;
476→}
