478→/**
479→ * Parse SDK error text and return a typed AgentError if detected.
480→ *
481→ * The SDK emits errors in two distinctive formats:
482→ * 1. "Error title · Action hint" - using middle dot (·, U+00B7) separator
483→ *    e.g., "Invalid API key · Fix external API key"
484→ * 2. "API Error: {status} {json}" - raw API error dump
485→ *    e.g., "API Error: 402 {"error":{"code":402,"message":"Payment required"}}"
486→ *
487→ * Returns null if text is not an SDK error.
488→ */
489→export function parseSDKErrorText(text: string): AgentError | null {
490→  const trimmed = text.trim();
491→  const isSingleLine = !trimmed.includes('\n');
492→  const isShortMessage = trimmed.length < 200;
493→
494→  // Format 1: Raw API error (e.g., "API Error: 402 {...}")
495→  // Extract status code and use it to determine error type
496→  if (trimmed.startsWith('API Error:') && isSingleLine) {
497→    const statusMatch = trimmed.match(/API Error:\s*(\d{3})/);
498→    if (statusMatch) {
499→      const statusCode = parseInt(statusMatch[1]!, 10);
500→      // Create error message with status code for parseError to detect
501→      return parseError(new Error(`${statusCode} ${trimmed}`));
502→    }
503→    // Fallback: just use the raw message
504→    return parseError(new Error(trimmed));
505→  }
506→
507→  // Format 2: Middle dot separator (e.g., "Invalid API key · Fix external API key")
508→  if (trimmed.includes(' · ') && isShortMessage && isSingleLine) {
509→    // The text before · is the error title, use it for parsing
510→    return parseError(new Error(trimmed));
511→  }
512→
513→  return null;
514→}
