 19→/**
 20→ * Parse an error message from a connection test into a user-friendly string.
 21→ */
 22→export function parseTestConnectionError(msg: string): string {
 23→  const lower = msg.toLowerCase()
 24→
 25→  if (lower.includes('econnrefused') || lower.includes('enotfound') || lower.includes('fetch failed')) {
 26→    return 'Cannot connect to API server. Check the URL and ensure the server is running.'
 27→  }
 28→  if (lower.includes('no api key found for')) {
 29→    return 'Provider mismatch during setup. Select a provider preset in Orcha Agents Backend API Key mode, or use Anthropic API Key mode for arbitrary compatible endpoints.'
 30→  }
 31→  if (lower.includes('401') || lower.includes('unauthorized') || lower.includes('authentication')) {
 32→    return 'Invalid API key'
 33→  }
 34→  if (lower.includes('404') && lower.includes('model')) {
 35→    return 'Model not found. Check the model name and try again.'
 36→  }
 37→  if (lower.includes('404')) {
 38→    return 'API endpoint not found. Check the URL.'
 39→  }
 40→  if (lower.includes('429') || lower.includes('rate limit')) {
 41→    return 'Rate limit exceeded. Please try again.'
 42→  }
 43→  if (lower.includes('403')) {
 44→    return 'API key does not have permission to access this resource'
 45→  }
 46→
 47→  return msg.slice(0, 300)
 48→}
