 53→export function validateSetupTestInput(params: {
 54→  provider: 'anthropic' | 'pi'
 55→  baseUrl?: string
 56→  piAuthProvider?: string
 57→}): { valid: true } | { valid: false; error: string } {
 58→  const hasCustomEndpoint = !!params.baseUrl?.trim()
 59→  if (params.provider === 'pi' && hasCustomEndpoint && !params.piAuthProvider) {
 60→    return {
 61→      valid: false,
 62→      error: 'Custom endpoint in Orcha Agents Backend mode requires selecting a provider preset. For arbitrary Anthropic-compatible endpoints, use Anthropic API Key mode.',
 63→    }
 64→  }
 65→
 66→  return { valid: true }
