 69→/**
 70→ * Returns true when a URL points to local loopback.
 71→ * Used to permit keyless setup tests for local model runtimes (e.g. Ollama).
 72→ */
 73→export function isLoopbackBaseUrl(baseUrl?: string): boolean {
 74→  if (!baseUrl?.trim()) return false
 75→  try {
 76→    const hostname = new URL(baseUrl.trim()).hostname
 77→    const normalizedHostname = hostname.startsWith('[') && hostname.endsWith(']')
 78→      ? hostname.slice(1, -1)
 79→      : hostname
 80→    return normalizedHostname === 'localhost' || normalizedHostname === '127.0.0.1' || normalizedHostname === '::1'
 81→  } catch {
 82→    return false
 83→  }
 84→}
