 86→/**
 87→ * Setup tests require API keys for non-local endpoints, but local loopback
 88→ * endpoints may be keyless.
 89→ */
 90→export function setupTestRequiresApiKey(baseUrl?: string): boolean {
 91→  return !isLoopbackBaseUrl(baseUrl)
 92→}
