  1→import type { SDKAssistantMessageError } from '@anthropic-ai/claude-agent-sdk';
  2→import type { AgentError } from './errors.ts';
  3→import type { LastApiError } from '../interceptor-common.ts';
  4→import { getProviderMetadata, getProviderDisplayName } from '../config/provider-metadata.ts';
  5→
  6→export interface ClaudeSdkApiError {
  7→  errorType: string;
  8→  message: string;
  9→  requestId?: string;
 10→}
 11→
 12→export interface ClaudeSdkErrorContext {
 13→  actualError: ClaudeSdkApiError | null;
 14→  capturedApiError: LastApiError | null;
 15→  providerType?: string;
 16→  piAuthProvider?: string;
 17→}
 18→
 19→type FailureKind = 'provider' | 'network' | 'unknown';
 20→
 21→const PROVIDER_HINTS = [
 22→  'internal server error',
 23→  'overloaded',
 24→  'service unavailable',
 25→  'bad gateway',
 26→  'gateway timeout',
 27→  'api_error',
 28→  'overloaded_error',
 29→  'upstream',
 30→] as const;
 31→
 32→const NETWORK_HINTS = [
 33→  'fetch failed',
 34→  'network',
 35→  'econnrefused',
 36→  'enotfound',
 37→  'timed out',
 38→  'timeout',
 39→  'dns',
 40→  'connection reset',
 41→  'connection refused',
 42→] as const;
 43→
 44→function normalize(value?: string | null): string {
 45→  return value?.toLowerCase() ?? '';
 46→}
 47→
 48→function includesAny(text: string, hints: readonly string[]): boolean {
 49→  return hints.some((hint) => text.includes(hint));
 50→}
 51→
 52→function formatStatus(error: LastApiError): string {
 53→  return error.statusText?.trim()
 54→    ? `${error.status} ${error.statusText}`
 55→    : String(error.status);
 56→}
 57→
 58→function buildApiDetails(context: ClaudeSdkErrorContext): string[] {
 59→  const details: string[] = [];
 60→
 61→  const add = (value?: string) => {
 62→    if (!value) return;
 63→    if (!details.includes(value)) details.push(value);
 64→  };
 65→
 66→  if (context.capturedApiError) {
 67→    add(`Status: ${formatStatus(context.capturedApiError)}`);
 68→    if (context.capturedApiError.message && context.capturedApiError.message !== context.capturedApiError.statusText) {
 69→      add(`API message: ${context.capturedApiError.message}`);
 70→    }
 71→  }
 72→
 73→  if (context.actualError?.message) {
 74→    add(`Error: ${context.actualError.message}`);
 75→  }
 76→
 77→  if (context.actualError?.errorType) {
 78→    add(`Type: ${context.actualError.errorType}`);
 79→  }
 80→
 81→  if (context.actualError?.requestId) {
 82→    add(`Request ID: ${context.actualError.requestId}`);
 83→  }
 84→
 85→  return details;
 86→}
 87→
 88→function classifyFailure(errorCode: SDKAssistantMessageError, context: ClaudeSdkErrorContext): FailureKind {
 89→  const status = context.capturedApiError?.status;
 90→  const actualType = normalize(context.actualError?.errorType);
 91→  const actualMessage = normalize(context.actualError?.message);
 92→  const capturedMessage = normalize(context.capturedApiError?.message);
 93→
 94→  const hasProviderStatus = typeof status === 'number' && (status >= 500 || status === 529);
 95→  const hasProviderType =
 96→    actualType.includes('api_error') ||
 97→    actualType.includes('overloaded') ||
 98→    actualType.includes('server_error');
 99→  const hasProviderText =
100→    includesAny(actualMessage, PROVIDER_HINTS) ||
101→    includesAny(capturedMessage, PROVIDER_HINTS);
102→  const hasNetworkText =
103→    includesAny(actualMessage, NETWORK_HINTS) ||
104→    includesAny(capturedMessage, NETWORK_HINTS);
105→
106→  // SDK explicit server_error should be treated as provider-side unless we have strong
107→  // evidence of local network failure and no provider-side signal.
108→  if (errorCode === 'server_error') {
109→    if (hasNetworkText && !hasProviderStatus && !hasProviderType && !hasProviderText) {
110→      return 'network';
111→    }
112→    return 'provider';
113→  }
114→
115→  if (hasProviderStatus || hasProviderType || hasProviderText) {
116→    return 'provider';
117→  }
118→
119→  if (hasNetworkText) {
120→    return 'network';
121→  }
122→
123→  return 'unknown';
124→}
125→
126→export function mapClaudeSdkAssistantError(
127→  errorCode: SDKAssistantMessageError,
128→  context: ClaudeSdkErrorContext,
