130→  const apiDetails = buildApiDetails(context);
131→  const failureKind = classifyFailure(errorCode, context);
132→  const providerInfo = getProviderMetadata(
133→    context.providerType ?? 'anthropic',
134→    context.piAuthProvider,
135→  ) ?? undefined;
136→
137→  const retryAction = [{ key: 'r', label: 'Retry', action: 'retry' as const }];
138→
139→  const providerError: AgentError = {
140→    code: 'provider_error',
141→    title: 'AI Provider Issue',
142→    message: 'The AI provider may be experiencing temporary issues. Please retry in a moment.',
143→    details: [
144→      ...apiDetails,
145→      'Your credentials and local setup may still be correct.',
146→    ],
147→    actions: retryAction,
148→    canRetry: true,
149→    retryDelayMs: 5000,
150→    providerInfo,
151→  };
152→
153→  const networkError: AgentError = {
154→    code: 'network_error',
155→    title: 'Connection Error',
156→    message: 'Unable to connect to the API server. Check your internet connection.',
157→    details: [
158→      ...apiDetails,
159→      'Verify your network connection is active',
160→      'Firewall or VPN may be blocking the connection',
161→    ],
162→    actions: retryAction,
163→    canRetry: true,
164→    retryDelayMs: 2000,
165→    providerInfo,
166→  };
167→
168→  switch (errorCode) {
169→    case 'authentication_failed':
170→      return {
171→        code: 'invalid_api_key',
172→        title: 'Authentication Failed',
173→        message: 'Unable to authenticate. Your API key may be invalid or expired.',
174→        details: ['Check your API key in settings', 'Ensure your API key has not been revoked'],
175→        actions: [
176→          { key: 's', label: 'Settings', action: 'settings' },
177→          { key: 'r', label: 'Retry', action: 'retry' },
178→        ],
179→        canRetry: true,
180→        retryDelayMs: 1000,
181→        providerInfo,
182→      };
183→
184→    case 'billing_error':
185→      return {
186→        code: 'billing_error',
187→        title: 'Billing Error',
188→        message: 'Your account has a billing issue.',
189→        details: ['Check your account billing status'],
190→        actions: [{ key: 's', label: 'Update credentials', action: 'settings' }],
191→        canRetry: false,
192→        providerInfo,
193→      };
194→
195→    case 'rate_limit':
196→      return {
197→        code: 'rate_limited',
198→        title: 'Rate Limit Exceeded',
199→        message: 'Too many requests. Please wait a moment before trying again.',
200→        details: ['Rate limits reset after a short period', 'Consider upgrading your plan for higher limits'],
201→        actions: retryAction,
202→        canRetry: true,
203→        retryDelayMs: 5000,
204→        providerInfo,
205→      };
206→
207→    case 'invalid_request':
208→      return {
209→        code: 'invalid_request',
210→        title: 'Invalid Request',
211→        message: 'The API rejected this request.',
212→        details: [
213→          ...apiDetails,
214→          'Try removing any attachments and resending',
215→          'Check if images are in a supported format (PNG, JPEG, GIF, WebP)',
216→        ],
217→        actions: retryAction,
218→        canRetry: true,
219→        retryDelayMs: 1000,
220→        providerInfo,
221→      };
222→
223→    case 'server_error':
224→      return failureKind === 'network' ? networkError : providerError;
225→
226→    case 'max_output_tokens':
227→      return {
228→        code: 'invalid_request',
229→        title: 'Output Too Large',
230→        message: 'The response exceeded the maximum output token limit.',
231→        details: ['Try breaking the task into smaller parts', 'Reduce the scope of the request'],
232→        actions: retryAction,
233→        canRetry: true,
234→        retryDelayMs: 1000,
235→        providerInfo,
236→      };
237→
238→    case 'unknown': {
239→      if (failureKind === 'provider') {
240→        return providerError;
241→      }
242→
243→      if (failureKind === 'network') {
244→        return networkError;
245→      }
246→
247→      return {
248→        code: 'unknown_error',
249→        title: 'Unknown Error',
250→        message: 'An unexpected error occurred.',
251→        details: [
252→          ...apiDetails,
253→          'This may be a temporary issue',
254→          'Check your network connection',
255→        ],
256→        actions: retryAction,
257→        canRetry: true,
258→        retryDelayMs: 2000,
259→        providerInfo,
260→      };
261→    }
262→
263→    default:
264→      return {
265→        code: 'unknown_error',
266→        title: 'Unknown Error',
267→        message: 'An unexpected error occurred.',
268→        details: [
269→          ...apiDetails,
270→          'This may be a temporary issue',
271→          'Check your network connection',
272→        ],
273→        actions: retryAction,
