 15→
 16→export type DiagnosticCode =
 17→  | 'billing_error'         // HTTP 402 from API
 18→  | 'token_expired'
 19→  | 'invalid_credentials'
 20→  | 'rate_limited'          // HTTP 429 from API
 21→  | 'mcp_unreachable'
 22→  | 'service_unavailable'
 23→  | 'unknown_error';
 24→
 25→export interface DiagnosticResult {
 26→  code: DiagnosticCode;
 27→  title: string;
 28→  message: string;
 29→  /** Diagnostic check results for debugging */
 30→  details: string[];
 31→}
