 43→interface CheckResult {
 44→  ok: boolean;
 45→  detail: string;
 46→  failCode?: DiagnosticCode;
 47→  failTitle?: string;
 48→  failMessage?: string;
 49→}
 50→
 51→/** Run a check with a timeout, returns default result if times out */
 52→async function withTimeout<T>(promise: Promise<T>, timeoutMs: number, defaultValue: T): Promise<T> {
 53→  const timeoutPromise = new Promise<T>((resolve) => setTimeout(() => resolve(defaultValue), timeoutMs));
 54→  return Promise.race([promise, timeoutPromise]);
 55→}
 56→
 57→/**
 58→ * Check if a recent API error was captured during the failed request.
 59→ * This is the most accurate source of truth for API failures since it
 60→ * captures the actual HTTP status code before the SDK wraps it.
 61→ *
 62→ * Provider-agnostic: HTTP status codes are universal.
 63→ */
 64→async function checkCapturedApiError(providerLabel: string): Promise<CheckResult> {
 65→  const apiError = getLastApiError();
 66→
 67→  if (!apiError) {
 68→    return { ok: true, detail: '✓ API error: None captured' };
 69→  }
 70→
 71→  // HTTP 402 - Payment Required
 72→  if (apiError.status === 402) {
 73→    return {
 74→      ok: false,
 75→      detail: `✗ API error: 402 ${apiError.message}`,
 76→      failCode: 'billing_error',
 77→      failTitle: 'Payment Required',
 78→      failMessage: apiError.message || `Your ${providerLabel} account has a billing issue.`,
 79→    };
 80→  }
 81→
 82→  // HTTP 401 - Unauthorized / Invalid Credentials
 83→  if (apiError.status === 401) {
 84→    return {
 85→      ok: false,
 86→      detail: `✗ API error: 401 ${apiError.message}`,
 87→      failCode: 'invalid_credentials',
 88→      failTitle: 'Invalid Credentials',
 89→      failMessage: apiError.message || 'Your API credentials are invalid or expired.',
 90→    };
 91→  }
 92→
 93→  // HTTP 429 - Rate Limited
 94→  if (apiError.status === 429) {
 95→    return {
 96→      ok: false,
 97→      detail: `✗ API error: 429 ${apiError.message}`,
 98→      failCode: 'rate_limited',
 99→      failTitle: 'Rate Limited',
100→      failMessage: 'Too many requests. Please wait a moment before trying again.',
101→    };
102→  }
103→
104→  // HTTP 5xx - Service Error
105→  if (apiError.status >= 500) {
106→    return {
107→      ok: false,
108→      detail: `✗ API error: ${apiError.status} ${apiError.message}`,
109→      failCode: 'service_unavailable',
110→      failTitle: `${providerLabel} Service Error`,
111→      failMessage: `The ${providerLabel} API returned an error (${apiError.status}). This is usually temporary.`,
112→    };
113→  }
114→
115→  // Other 4xx errors - report but don't fail (might be expected)
116→  // Include the message so users can see what actually went wrong
117→  return { ok: true, detail: `✓ API error: ${apiError.status} - ${apiError.message}` };
118→}
