444→/**
445→ * Provider-agnostic stored-connection validation.
446→ * Moves provider/auth branching out of Electron main IPC handlers.
447→ */
448→export async function validateStoredBackendConnection(args: {
449→  slug: string;
450→  hostRuntime: BackendHostRuntimeContext;
451→}): Promise<StoredConnectionValidationResult> {
452→  try {
453→    const connection = getLlmConnection(args.slug);
454→    if (!connection) {
455→      return { success: false, error: 'Connection not found' };
456→    }
457→
458→    const credentialManager = getCredentialManager();
459→    const hasCredentials = await credentialManager.hasLlmCredentials(
460→      args.slug,
461→      connection.authType,
462→      connection.providerType,
463→    );
464→
465→    if (!hasCredentials && connection.authType !== 'none') {
466→      return { success: false, error: 'No credentials configured' };
467→    }
468→
469→    const provider = providerTypeToAgentProvider(connection.providerType);
470→    const { driver, resolvedPaths } = resolveDriverRuntime(provider, args.hostRuntime);
471→
472→    driver.initializeHostRuntime?.({
473→      hostRuntime: args.hostRuntime,
474→      resolvedPaths,
475→    });
476→
477→    if (!driver.validateStoredConnection) {
478→      return { success: true };
479→    }
480→
481→    return driver.validateStoredConnection({
482→      slug: args.slug,
483→      connection,
484→      credentialManager,
485→      hostRuntime: args.hostRuntime,
486→      resolvedPaths,
487→    });
488→  } catch (error) {
489→    const msg = error instanceof Error ? error.message : String(error);
490→    return { success: false, error: parseValidationError(msg) };
491→  }
492→}
