124→/**
125→ * Get Pi models for a specific auth provider directly from the Pi SDK.
126→ */
127→export function getPiModelsForAuthProvider(piAuthProvider: string): ModelDefinition[] {
128→  let result: ModelDefinition[] = [];
129→
130→  try {
131→    const models = getModels(piAuthProvider as KnownProvider);
132→    if (models.length > 0) {
133→      result = models
134→        .filter(m => !isExcludedPiModel(m.id))
135→        // Bedrock: exclude bare Claude models without region prefix — they're
136→        // always rejected by Bedrock which requires inference profiles (us.*/eu.*/global.*).
137→        // Regional variants from the same catalog are kept.
138→        .filter(m => piAuthProvider !== 'amazon-bedrock' || !isBareBedrockClaudeModel(m.id))
139→        .map(piModelToDefinition);
140→    }
141→  } catch {
142→    // Provider not recognized by SDK — fall through
143→  }
144→
145→  // Append custom ZAI models not yet in the Pi SDK (auto-deduplicates)
146→  if (piAuthProvider === 'zai') {
147→    const sdkIds = new Set(result.map(m => m.id));
148→    for (const custom of ZAI_CUSTOM_MODELS) {
149→      if (!sdkIds.has(custom.id)) {
150→        result.push(custom);
151→      }
152→    }
153→  }
154→
155→  return result;
156→}
