220→/** Convert 'vercel-ai-gateway' → 'Vercel Ai Gateway' etc. */
221→function formatProviderName(key: string): string {
222→  return key.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
223→}
