225→/**
226→ * Get all Pi providers available for API key authentication.
227→ */
228→export function getPiApiKeyProviders(): PiProviderInfo[] {
229→  return getProviders()
230→    .filter(p => !PI_EXCLUDED_PROVIDERS.has(p))
231→    .map(p => {
232→      const display = PI_PROVIDER_DISPLAY[p];
233→      return {
234→        key: p,
235→        label: display?.label ?? formatProviderName(p),
236→        placeholder: display?.placeholder ?? 'sk-...',
237→      };
238→    })
239→    .sort((a, b) => {
240→      const priority = ['anthropic', 'google', 'openai'];
241→      const ai = priority.indexOf(a.key);
242→      const bi = priority.indexOf(b.key);
243→      if (ai !== -1 && bi !== -1) return ai - bi;
244→      if (ai !== -1) return -1;
245→      if (bi !== -1) return 1;
246→      return a.label.localeCompare(b.label);
247→    });
248→}
