281→
282→  /**
283→   * Ensure the subprocess is spawned and ready.
284→   * Lazy initialization -- spawns on first use.
285→   */
286→  private async ensureSubprocess(): Promise<void> {
287→    if (this.subprocess && this.subprocessReady) {
288→      await this.subprocessReady;
289→      return;
290→    }
291→
292→    await this.spawnSubprocess();
