294→
295→  /**
296→   * Spawn the pi-agent-server subprocess and set up JSONL communication.
297→   */
298→  private async spawnSubprocess(): Promise<void> {
299→    const runtime = getBackendRuntime(this.config);
300→    const piServerPath = runtime.paths?.piServer;
301→    if (!piServerPath) {
302→      throw new Error('piServerPath not configured. Cannot spawn Pi subprocess.');
303→    }
304→
305→    const nodePath = runtime.paths?.node || process.execPath;
306→    const cwd = this.resolvedCwd();
307→
308→    this.debug(`Spawning Pi subprocess: ${nodePath} ${piServerPath}`);
309→    this.resetSubprocessErrorDedup();
310→
311→    // Set up ready promise before spawning
312→    this.subprocessReady = new Promise<void>((resolve) => {
313→      this.subprocessReadyResolve = resolve;
314→    });
315→
316→    // Build session ID and session dir path upfront (used for spawn env + init command)
317→    const sessionId = this.config.session?.id || `agent-${Date.now()}`;
318→    const sessionDir = this.config.session
319→      ? join(this.config.workspace.rootPath, 'sessions', sessionId)
320→      : undefined;
321→
322→    // Build spawn args — optionally preload the network interceptor
323→    // for tool metadata injection/capture across all API formats.
324→    const args = [piServerPath];
325→    const interceptorPath = runtime.paths?.interceptor;
326→    if (interceptorPath) {
327→      args.unshift('--require', interceptorPath);
328→    }
329→
330→    // Resolve credentials before spawning so we can derive AWS env vars
331→    // from the same fetch that produces piAuth (single source of truth).
332→
333→    // For Copilot OAuth: preemptively refresh the short-lived Copilot token
334→    // before fetching credentials, so getPiAuth() picks up a fresh token.
335→    // refreshAndPushTokens guards this.subprocess internally — safe to call pre-spawn.
336→    if (this.config.authType === 'oauth' && runtime.piAuthProvider === 'github-copilot') {
337→      const slug = this.config.connectionSlug || 'pi';
338→      const stored = await getCredentialManager().getLlmOAuth(slug);
339→      if (stored?.refreshToken && (!stored.expiresAt || stored.expiresAt < Date.now() + 5 * 60_000)) {
340→        this.debug('Copilot token expired or expiring soon — refreshing before session start');
341→        await this.refreshAndPushTokens();
342→      }
343→    }
344→
345→    // Retrieve auth credentials for the subprocess.
346→    // Custom endpoint mode must NOT fall back to global API keys — keyless local endpoints
347→    // are valid, and non-local endpoints should fail explicitly instead of using unrelated creds.
348→    const piAuth = await this.getPiAuth();
349→    const isCustomEndpointMode = !!runtime.customEndpoint;
350→    const legacyApiKey = (!piAuth && !isCustomEndpointMode) ? await this.getApiKey() : undefined;
351→    if (isCustomEndpointMode && !piAuth) {
352→      this.debug('Custom endpoint mode: no provider credential configured, sending empty API key');
353→    }
354→
355→    // Derive AWS env vars from the piAuth credential (single fetch, no race).
356→    const awsEnv = this.buildAwsEnv(piAuth, runtime);
357→
358→    // Spawn the subprocess
359→    const child = spawn(nodePath, args, {
360→      cwd,
361→      stdio: ['pipe', 'pipe', 'pipe'],
362→      env: {
363→        ...process.env,
364→        ...getProxyEnvVars(),
365→        ...this.config.envOverrides,
366→        ...awsEnv,
367→        // Pass session dir for cross-process toolMetadataStore
368→        ...(sessionDir ? { CRAFT_SESSION_DIR: sessionDir } : {}),
369→        // Propagate debug mode
370→        CRAFT_DEBUG: (process.argv.includes('--debug') || process.env.CRAFT_DEBUG === '1') ? '1' : '0',
371→      },
372→    });
373→
374→    this.subprocess = child;
375→
376→    // Set up readline for JSONL parsing from stdout
377→    this.readline = createInterface({
378→      input: child.stdout!,
379→      crlfDelay: Infinity,
380→    });
381→
382→    this.readline.on('line', (line: string) => {
383→      this.handleLine(line);
384→    });
385→
386→    // Forward stderr to debug log
387→    child.stderr?.on('data', (data: Buffer) => {
388→      const text = data.toString().trim();
389→      if (text) {
390→        this.debug(`[subprocess stderr] ${text}`);
391→      }
392→    });
393→
394→    // Handle subprocess exit
395→    child.on('exit', (code, signal) => {
396→      this.handleSubprocessExit(code, signal);
397→    });
398→
399→    child.on('error', (error) => {
400→      this.debug(`Subprocess error: ${error.message}`);
401→      this.resetSubprocessErrorDedup();
402→      this.eventQueue.enqueue({ type: 'error', message: `Pi subprocess error: ${error.message}` });
403→      this.eventQueue.complete();
404→    });
405→
406→    const sessionPath = this.config.session
407→      ? getSessionPath(this.config.workspace.rootPath, sessionId)
408→      : '';
409→    const plansFolderPath = getSessionPlansPath(this.config.workspace.rootPath, sessionId);
410→    const workingDirectory = this.config.session?.workingDirectory || cwd;
411→
412→    // Send init command (flat structure matching subprocess InboundMessage type)
413→    this.send({
414→      type: 'init',
415→      apiKey: legacyApiKey || '',
416→      model: this._model,
417→      cwd,
418→      thinkingLevel: this._thinkingLevel,
419→      workspaceRootPath: this.config.workspace.rootPath,
420→      sessionId,
421→      sessionPath,
422→      workingDirectory,
423→      plansFolderPath,
424→      miniModel: this.config.miniModel,
425→      providerType: this.config.providerType,
426→      authType: this.config.authType,
427→      workspaceId: this.config.workspace.id,
428→      piAuth,
429→      baseUrl: runtime.baseUrl,
430→      customEndpoint: runtime.customEndpoint,
431→      customModels: runtime.customModels,
432→      // Branch params for Pi SDK session fork
433→      branchFromSdkSessionId: this.config.session?.branchFromSdkSessionId,
434→      branchFromSessionPath: this.config.session?.branchFromSessionPath,
435→      branchFromSdkTurnId: this.config.session?.branchFromSdkTurnId,
436→    });
437→
438→    // Wait for subprocess to report ready
439→    await this.subprocessReady;
440→    this.debug('Pi subprocess is ready');
441→
442→    // Ensure auto-compaction is explicitly enabled for embedded sessions.
443→    // PI defaults this to enabled, but we set it proactively for clarity and resilience.
444→    try {
445→      const enabled = await this.requestSetAutoCompaction(true);
446→      this.debug(`PI auto-compaction enabled: ${enabled}`);
447→    } catch (error) {
448→      this.debug(`Failed to configure PI auto-compaction (continuing): ${error instanceof Error ? error.message : String(error)}`);
449→    }
450→
451→    // Register session-scoped tools as proxy tools in the subprocess.
452→    // These tools (SubmitPlan, config_validate, source auth, call_llm, etc.)
453→    // are executed in the main process when the LLM calls them.
454→    this.assertBackendSessionToolParity();
455→    const sessionToolDefs = getSessionToolProxyDefs();
456→
457→    // Patch call_llm description with provider-specific model hint
458→    if (this.config.miniModel) {
459→      const callLlmDef = sessionToolDefs.find(d => d.name === 'mcp__session__call_llm');
460→      if (callLlmDef) {
461→        callLlmDef.description += `\n\nDefault fast model for this session: ${this.config.miniModel}. Omit the model parameter to use it automatically.`;
462→      }
463→    }
464→
465→    this.send({
466→      type: 'register_tools',
467→      tools: sessionToolDefs,
468→    });
469→    this.debug(`Registered ${sessionToolDefs.length} session tools with subprocess`);
470→
471→    // If pool has source tools, register them with the subprocess.
472→    this.registerPoolToolsWithSubprocess();
473→  }
474→
475→  /**
476→   * Send pool's proxy tool defs to subprocess for model visibility.
477→   */
478→  private registerPoolToolsWithSubprocess(): void {
