  6→// ── Copilot model types ────────────────────────────────────────────────
  7→type RawCopilotModel = {
  8→  id: string;
  9→  name: string;
 10→  supportedReasoningEfforts?: string[];
 11→  policy?: { state: string };
 12→  contextWindow?: number;
 13→};
 14→
 15→// ── Direct HTTP approach ─────────────────────────────────────────────
 16→
 17→/** Headers that identify us as a VS Code Copilot client (same as Pi SDK). */
 18→const COPILOT_HEADERS = {
 19→  'User-Agent': 'GitHubCopilotChat/0.35.0',
 20→  'Editor-Version': 'vscode/1.107.0',
 21→  'Editor-Plugin-Version': 'copilot-chat/0.35.0',
 22→  'Copilot-Integration-Id': 'vscode-chat',
 23→} as const;
 24→
 25→/** Extract API base URL from a Copilot API token's proxy-ep field. */
 26→function getBaseUrlFromToken(token: string): string | null {
 27→  const match = token.match(/proxy-ep=([^;]+)/);
 28→  if (!match?.[1]) return null;
 29→  const apiHost = match[1].replace(/^proxy\./, 'api.');
 30→  return `https://${apiHost}`;
 31→}
 32→
 33→/**
 34→ * Fetch models directly from the Copilot API via HTTP.
 35→ *
 36→ * 1. Exchange GitHub OAuth token → Copilot API token (via Pi SDK)
 37→ * 2. Extract base URL from token's proxy-ep field
 38→ * 3. GET /models to list available models with policy state
 39→ *
 40→ * No CLI subprocess, no PATH issues, no env contamination.
 41→ */
 42→async function listModelsViaHttp(
 43→  githubToken: string,
 44→  timeoutMs: number,
 45→): Promise<RawCopilotModel[]> {
 46→  const { refreshGitHubCopilotToken } = await import('@mariozechner/pi-ai/oauth');
 47→
 48→  // Step 1: Exchange GitHub OAuth token → Copilot API token
 49→  const creds = await refreshGitHubCopilotToken(githubToken);
 50→  const copilotToken = creds.access;
 51→
 52→  // Step 2: Extract base URL from token
 53→  const baseUrl = getBaseUrlFromToken(copilotToken);
 54→  if (!baseUrl) {
 55→    throw new Error('Could not extract API base URL from Copilot token (missing proxy-ep)');
 56→  }
 57→
 58→  console.warn(`[listModelsViaHttp] token exchange OK, baseUrl=${baseUrl}`);
 59→
 60→  // Step 3: GET /models
 61→  const controller = new AbortController();
 62→  const timer = setTimeout(() => controller.abort(), timeoutMs);
 63→
 64→  try {
 65→    const res = await fetch(`${baseUrl}/models`, {
 66→      method: 'GET',
 67→      signal: controller.signal,
 68→      headers: {
 69→        'Authorization': `Bearer ${copilotToken}`,
 70→        ...COPILOT_HEADERS,
 71→      },
 72→    });
 73→
 74→    if (!res.ok) {
 75→      const text = await res.text().catch(() => '');
 76→      throw new Error(`Copilot API ${res.status}: ${text.slice(0, 300)}`);
 77→    }
 78→
 79→    const data = await res.json() as Record<string, unknown>;
 80→    // Handle both { models: [...] } and { data: [...] } response formats
 81→    const models = (data.models || data.data || []) as Record<string, unknown>[];
 82→
 83→    console.warn(`[listModelsViaHttp] GET /models returned ${models.length} models`);
 84→
 85→    return models.map(m => ({
 86→      id: m.id as string,
 87→      name: (m.name || m.id) as string,
 88→      supportedReasoningEfforts: (m.supportedReasoningEfforts || m.supported_reasoning_efforts) as string[] | undefined,
 89→      policy: m.policy as { state: string } | undefined,
 90→      contextWindow: ((m.capabilities as Record<string, unknown>)?.limits as Record<string, unknown>)?.max_context_window_tokens as number | undefined,
 91→    }));
 92→  } catch (err) {
 93→    if ((err as Error).name === 'AbortError') {
 94→      throw new Error('Copilot models API timed out');
 95→    }
 96→    throw err;
 97→  } finally {
 98→    clearTimeout(timer);
 99→  }
100→}
