102→/** Model ID prefixes to exclude — legacy models that clutter the selector. */
103→const EXCLUDED_MODEL_PREFIXES = ['gpt-4', 'gpt-3.5'];
104→
105→/** Filter raw models to only those explicitly enabled by policy, excluding legacy models. */
106→function filterEnabledModels(models: RawCopilotModel[]): RawCopilotModel[] {
107→  return models.filter(m =>
108→    m.policy?.state === 'enabled'
109→    && !EXCLUDED_MODEL_PREFIXES.some(prefix => m.id.startsWith(prefix)),
110→  );
111→}
112→
113→/** Convert raw Copilot models to our ModelDefinition format. */
114→function toModelDefinitions(models: RawCopilotModel[]): ModelDefinition[] {
115→  return models.map(m => ({
116→    id: m.id,
117→    name: m.name,
118→    shortName: m.name,
119→    description: '',
120→    provider: 'pi' as const,
121→    contextWindow: m.contextWindow || 200_000,
122→    supportsThinking: !!(m.supportedReasoningEfforts && m.supportedReasoningEfforts.length > 0),
123→  }));
124→}
125→
126→/** Log a breakdown of models by policy state. */
127→function logModelBreakdown(tag: string, models: RawCopilotModel[]): void {
128→  const byState = new Map<string, string[]>();
129→  for (const m of models) {
130→    const state = m.policy?.state ?? 'no-policy';
131→    const list = byState.get(state) ?? [];
132→    list.push(m.id);
133→    byState.set(state, list);
134→  }
135→  const breakdown = [...byState.entries()].map(([s, ids]) => `${s}=${ids.length}(${ids.join(',')})`).join('; ');
136→  console.warn(`[fetchCopilotModels] ${tag}: total=${models.length} enabled=${filterEnabledModels(models).length} | ${breakdown}`);
137→}
