139→/**
140→ * Fetch Copilot models with a 2-tier fallback chain:
141→ *
142→ * 1. **Direct HTTP API** – exchange the Pi SDK's GitHub OAuth token for
143→ *    a Copilot API token, then GET /models. Returns the live model list
144→ *    with policy state, so we show only enabled models. No CLI subprocess,
145→ *    no PATH issues, no env contamination.
146→ * 2. **Pi SDK static catalog** – hardcoded model registry shipped with
147→ *    the Pi SDK. Not filtered by the user's policy but always available
148→ *    as a last resort.
149→ */
150→async function fetchCopilotModels(
151→  piSdkGitHubToken: string,
152→  timeoutMs: number,
153→): Promise<ModelDefinition[]> {
154→
155→  // ── Tier 1: Direct HTTP API ──────────────────────────────────────
156→  try {
157→    const raw = await listModelsViaHttp(piSdkGitHubToken, timeoutMs);
158→    if (raw.length > 0) {
159→      logModelBreakdown('tier1-httpApi', raw);
160→      const enabled = filterEnabledModels(raw);
161→      if (enabled.length > 0) {
162→        return toModelDefinitions(enabled);
163→      }
164→      // All models disabled by policy — unusual but possible.
165→      // Log it clearly and fall through to static catalog.
166→      console.warn(`[fetchCopilotModels] tier1-httpApi: ${raw.length} models returned but 0 enabled by policy`);
167→    }
168→  } catch (err) {
169→    console.warn(`[fetchCopilotModels] tier1-httpApi failed: ${(err as Error).message}`);
170→  }
171→
172→  // ── Tier 2: Pi SDK static catalog (last resort) ──────────────────
173→  const staticModels = getPiModelsForAuthProvider('github-copilot');
174→  if (staticModels.length > 0) {
175→    console.warn(`[fetchCopilotModels] tier2-staticCatalog: falling back to ${staticModels.length} Pi SDK models`);
176→    return staticModels;
177→  }
178→
179→  throw new Error('No Copilot models available from any source.');
180→}
