182→/**
183→ * Lightweight direct HTTP test for Pi providers that expose an Anthropic-compatible
184→ * messages endpoint. Avoids spawning a full Pi subprocess (which can exceed the
185→ * 20s test timeout due to SDK initialization overhead).
186→ */
187→async function testAnthropicCompatible(
188→  apiKey: string,
189→  baseUrl: string,
190→  model: string,
191→  timeoutMs: number,
192→): Promise<{ success: boolean; error?: string }> {
193→  const url = `${baseUrl.replace(/\/$/, '')}/v1/messages`;
194→  const controller = new AbortController();
195→  const timer = setTimeout(() => controller.abort(), timeoutMs);
196→
197→  try {
198→    const res = await fetch(url, {
199→      method: 'POST',
200→      signal: controller.signal,
201→      headers: {
202→        'content-type': 'application/json',
203→        'x-api-key': apiKey,
204→        'anthropic-version': '2023-06-01',
205→      },
206→      body: JSON.stringify({
207→        model,
208→        max_tokens: 16,
209→        messages: [{ role: 'user', content: 'Say ok' }],
210→      }),
211→    });
212→
213→    if (res.ok) return { success: true };
214→
215→    const text = await res.text().catch(() => '');
216→    return { success: false, error: `${res.status} ${text}`.slice(0, 500) };
217→  } catch (err) {
218→    if ((err as Error).name === 'AbortError') {
219→      return { success: false, error: 'Connection test timed out' };
220→    }
221→    return { success: false, error: (err as Error).message };
222→  } finally {
223→    clearTimeout(timer);
224→  }
225→}
