217→// Speculative prefetch for read-only tools (enables parallel execution despite Pi SDK's sequential loop).
218→// When the LLM emits multiple call_llm tool calls in a single message, we fire all requests
219→// to the main process in parallel on message_end (before executeToolCalls iterates sequentially).
220→// Each proxy tool's execute() then hits the cache instead of sending a new request.
221→const PREFETCHABLE_TOOLS = new Set(['call_llm']);
222→const prefetchCache = new Map<string, Promise<{ content: string; isError: boolean }>>();
223→
224→function isPrefetchableTool(toolName: string): boolean {
225→  const stripped = toolName.replace(/^(mcp__session__|session__)/, '');
226→  return PREFETCHABLE_TOOLS.has(stripped);
