236→// ============================================================
237→// JSONL I/O
238→// ============================================================
239→
240→function send(msg: OutboundMessage): void {
241→  const line = JSON.stringify(msg);
242→  process.stdout.write(line + '\n');
243→}
244→
245→function debugLog(message: string): void {
246→  // Write debug messages to stderr so they don't interfere with JSONL protocol
247→  process.stderr.write(`[pi-server] ${message}\n`);
248→}
