250→/** Find the most recent .jsonl session file in a directory. */
251→function findMostRecentSessionFile(sessionDir: string): string | null {
252→  if (!existsSync(sessionDir)) return null;
253→  let best: { path: string; mtime: number } | null = null;
254→  for (const entry of readdirSync(sessionDir)) {
255→    if (!entry.endsWith('.jsonl')) continue;
256→    const fullPath = join(sessionDir, entry);
257→    const mtime = statSync(fullPath).mtimeMs;
258→    if (!best || mtime > best.mtime) {
259→      best = { path: fullPath, mtime };
260→    }
261→  }
262→  return best?.path ?? null;
263→}
