265→// ============================================================
266→// Callback Server (for call_llm from session MCP server)
267→// ============================================================
268→
269→async function startCallbackServer(): Promise<void> {
270→  if (callbackServer) return;
271→
272→  const server = http.createServer(async (req, res) => {
273→    if (req.method !== 'POST' || req.url !== '/call-llm') {
274→      res.writeHead(404);
275→      res.end();
276→      return;
277→    }
278→    try {
279→      const chunks: Buffer[] = [];
280→      for await (const chunk of req) chunks.push(chunk as Buffer);
281→      const body = JSON.parse(Buffer.concat(chunks).toString()) as Record<string, unknown>;
282→
283→      debugLog('Received call_llm request via callback server');
284→      const result = await preExecuteCallLlm(body);
285→      res.writeHead(200, { 'Content-Type': 'application/json' });
286→      res.end(JSON.stringify(result));
287→    } catch (error) {
288→      const msg = error instanceof Error ? error.message : String(error);
289→      debugLog(`call_llm via callback failed: ${msg}`);
290→      res.writeHead(200, { 'Content-Type': 'application/json' });
291→      res.end(JSON.stringify({ error: msg }));
292→    }
293→  });
294→
295→  await new Promise<void>((resolve, reject) => {
296→    server.listen(0, '127.0.0.1', () => {
297→      const addr = server.address();
298→      callbackPort = typeof addr === 'object' && addr ? addr.port : 0;
299→      debugLog(`Callback server listening on 127.0.0.1:${callbackPort}`);
300→      resolve();
301→    });
302→    server.on('error', reject);
303→  });
304→
305→  callbackServer = server;
306→}
307→
308→function stopCallbackServer(): void {
309→  if (callbackServer) {
310→    callbackServer.close();
311→    callbackServer = null;
312→    callbackPort = 0;
313→  }
314→}
