316→// ============================================================
317→// Pi Session Management
318→// ============================================================
319→
320→function resolvedCwd(): string {
321→  const wd = initConfig?.cwd || initConfig?.workingDirectory || process.cwd();
322→  if (wd.startsWith('~/')) return join(homedir(), wd.slice(2));
323→  if (wd === '~') return homedir();
324→  return wd;
325→}
326→
327→// Helper: derive preferCustomEndpoint flag from init config
328→function shouldPreferCustomEndpoint(): boolean {
329→  return Boolean(initConfig?.customEndpoint && initConfig?.baseUrl?.trim());
330→}
331→
332→/**
333→ * Expose the active Pi model API/provider/base URL to the interceptor process.
334→ * This gives the interceptor a robust routing hint (instead of brittle URL-only matching).
335→ */
336→function setInterceptorApiHints(model: { api?: string; provider?: string; baseUrl?: string } | undefined): void {
337→  if (!model) {
338→    delete process.env.CRAFT_PI_MODEL_API;
339→    delete process.env.CRAFT_PI_MODEL_PROVIDER;
340→    delete process.env.CRAFT_PI_MODEL_BASE_URL;
341→    return;
342→  }
343→
344→  process.env.CRAFT_PI_MODEL_API = model.api || '';
345→  process.env.CRAFT_PI_MODEL_PROVIDER = model.provider || '';
346→  process.env.CRAFT_PI_MODEL_BASE_URL = model.baseUrl || '';
347→
348→  debugLog(
349→    `[interceptor-hint] api=${process.env.CRAFT_PI_MODEL_API || '-'} provider=${process.env.CRAFT_PI_MODEL_PROVIDER || '-'} baseUrl=${process.env.CRAFT_PI_MODEL_BASE_URL || '-'}`,
350→  );
351→}
352→
353→/** Strip bare model IDs (remove pi/ prefix if present) */
354→function stripPiPrefix(id: string): string {
355→  return id.startsWith('pi/') ? id.slice(3) : id;
356→}
357→
358→/**
359→ * Resolve the API key for custom endpoint auth.
360→ * Returns empty string for local endpoints (Ollama etc.) that don't need auth.
361→ */
362→function resolveCustomEndpointApiKey(): string {
363→  if (initConfig?.piAuth?.credential?.type === 'api_key') {
364→    return initConfig.piAuth.credential.key;
365→  }
366→  const key = initConfig?.apiKey || '';
367→  if (!key && initConfig?.baseUrl && !isLocalhostUrl(initConfig.baseUrl)) {
368→    debugLog('[custom-endpoint] Warning: no API key found for non-localhost endpoint — requests will likely fail');
369→  }
370→  return key;
371→}
372→
373→function isLocalhostUrl(url: string): boolean {
374→  try {
375→    const hostname = new URL(url).hostname;
376→    const normalizedHostname = hostname.startsWith('[') && hostname.endsWith(']')
377→      ? hostname.slice(1, -1)
378→      : hostname;
379→    return normalizedHostname === 'localhost' || normalizedHostname === '127.0.0.1' || normalizedHostname === '::1';
380→  } catch {
381→    return false;
382→  }
383→}
384→
385→/** Model IDs currently registered under the custom-endpoint provider */
386→let customEndpointModelIds: Set<string> = new Set();
387→
388→interface CustomModelEntry extends CustomEndpointModelOverrides {
389→  id: string;
390→}
391→
392→/**
393→ * Register (or re-register) the custom-endpoint provider with the given models.
394→ * Note: registerProvider replaces the entire provider, so we maintain a Set of all
395→ * known model IDs and always pass the full set.
396→ */
397→const customModelOverrides = new Map<string, CustomEndpointModelOverrides>();
398→
399→function registerCustomEndpointModels(
400→  registry: PiModelRegistry,

400→  registry: PiModelRegistry,
401→  api: CustomEndpointApi,
402→  baseUrl: string,
403→  models: CustomModelEntry[],
404→): void {
405→  for (const m of models) {
406→    customEndpointModelIds.add(m.id);
407→    if (m.contextWindow || m.supportsImages !== undefined) {
408→      customModelOverrides.set(m.id, {
409→        ...(m.contextWindow ? { contextWindow: m.contextWindow } : {}),
410→        ...(m.supportsImages !== undefined ? { supportsImages: m.supportsImages } : {}),
411→      });
412→    }
413→  }
414→  const allIds = [...customEndpointModelIds];
415→  registry.registerProvider('custom-endpoint', {
416→    baseUrl,
417→    apiKey: resolveCustomEndpointApiKey(),
418→    api,
419→    authHeader: true,
420→    models: allIds.map(id => buildCustomEndpointModelDef(
421→      id,
422→      { supportsImages: initConfig?.customEndpoint?.supportsImages === true },
423→      customModelOverrides.get(id),
424→    )),
425→  });
426→  debugLog(`Registered custom endpoint: ${baseUrl} with ${allIds.length} model(s) [${allIds.join(', ')}], api: ${api}`);
427→}
428→
429→/**
430→ * Create an in-memory auth storage pre-loaded with the user's credentials
431→ * and a model registry backed by it. Used by both the main session and
432→ * ephemeral queryLlm sessions.
433→ */
434→function createAuthenticatedRegistry(): {
435→  authStorage: PiAuthStorage;
436→  modelRegistry: PiModelRegistry;
437→} {
438→  // Reuse module-level authStorage if already created (allows token_update to mutate it).
439→  // Only create a new one on first call or after re-init.
440→  if (!moduleAuthStorage) {
441→    moduleAuthStorage = PiAuthStorage.inMemory();
442→  }
443→  const authStorage = moduleAuthStorage;
444→  if (initConfig?.piAuth) {
445→    const { provider, credential } = initConfig.piAuth;
446→    authStorage.set(provider, credential);
447→    debugLog(`Injected ${credential.type} credential for provider: ${provider}`);
448→  } else if (initConfig?.apiKey) {
449→    authStorage.set('anthropic', { type: 'api_key', key: initConfig.apiKey });
450→    debugLog('Injected API key into auth storage (legacy fallback)');
451→  }
452→
453→  const modelRegistry = PiModelRegistry.inMemory(authStorage);
454→
455→  // Register custom endpoint models dynamically via Pi SDK's registerProvider API.
456→  // This makes arbitrary OpenAI/Anthropic-compatible endpoints work through the Pi SDK
457→  // by creating synthetic Model<Api> objects that the SDK requires.
458→  const hasCustomEndpoint = !!initConfig?.baseUrl?.trim();
459→  if (hasCustomEndpoint && initConfig?.customEndpoint) {
460→    const { api } = initConfig.customEndpoint;
461→    const modelEntries: CustomModelEntry[] = (initConfig.customModels?.length
462→      ? initConfig.customModels
463→      : [initConfig.model || 'default']
464→    ).map(m => typeof m === 'string'
465→      ? { id: stripPiPrefix(m) }
466→      : { id: stripPiPrefix(m.id), contextWindow: m.contextWindow });
467→    customEndpointModelIds = new Set();  // Reset on fresh registry creation
468→    registerCustomEndpointModels(modelRegistry, api, initConfig.baseUrl!.trim(), modelEntries);
469→  } else if (hasCustomEndpoint && !initConfig?.customEndpoint) {
470→    debugLog('Custom endpoint without protocol config — models may not resolve. Set customEndpoint.api for proper routing.');
471→  }
472→
473→  return { authStorage, modelRegistry };
474→}
475→
476→async function ensureSession(): Promise<AgentSession> {
477→  if (piSession) return piSession;
478→  if (!initConfig) throw new Error('Cannot create session: init not received');
479→
480→  const cwd = resolvedCwd();
481→
482→  const { authStorage, modelRegistry } = createAuthenticatedRegistry();
483→  // Store at module scope for set_model handler
484→  piModelRegistry = modelRegistry;
485→
486→  // Build tools: coding tools + web tools wrapped with permission hooks + proxy tools.
487→  // Search provider is selected based on the user's LLM connection:
488→  //   - OpenAI/OpenRouter → Responses API built-in web_search
489→  //   - ChatGPT Plus (openai-codex) → ChatGPT backend responses endpoint
490→  //   - Google → Gemini API with googleSearch grounding
491→  //   - Others → DuckDuckGo fallback
492→  //
493→  // IMPORTANT: resolve dynamically on each search call so token_update refreshes
494→  // are used without recreating the session.
495→  const searchProvider = {
496→    get name() {
497→      return resolveSearchProvider(initConfig?.piAuth).name;
498→    },
499→    async search(query: string, count: number) {
500→      return resolveSearchProvider(initConfig?.piAuth).search(query, count);
501→    },
502→  };
503→  const searchTool = createSearchTool(searchProvider);
504→  const webFetchTool = createWebFetchTool(() =>
505→    initConfig ? getSessionPath(initConfig.workspaceRootPath, initConfig.sessionId) : null
506→  );
507→  const webTools = [searchTool, webFetchTool];
508→  const wrappedCodingTools = wrapToolsWithHooks([...codingTools, ...webTools]);
509→  const proxyTools = buildProxyTools();
510→  const allTools = [...wrappedCodingTools, ...proxyTools];
511→  debugLog(`Session tools: ${wrappedCodingTools.length} coding + ${proxyTools.length} proxy = ${allTools.length} total`);
512→
513→  // Build session options
514→  const sessionOptions: CreateAgentSessionOptions = {
515→    cwd,
516→    authStorage,
517→    modelRegistry,
518→    tools: allTools,
519→  };
520→
521→  // Extension isolation: set agentDir to a temp directory under session path
522→  // to prevent loading global Pi extensions from ~/.pi/agent
523→  if (initConfig.sessionPath) {
524→    const agentDir = initConfig.agentDir || join(initConfig.sessionPath, '.pi-agent');
525→    mkdirSync(agentDir, { recursive: true });
526→    sessionOptions.agentDir = agentDir;
527→
528→    // Session resume: use a per-Craft-session directory so the Pi SDK can
529→    // persist and resume its own session across subprocess restarts.
530→    // continueRecent() loads the existing session if one exists, otherwise
531→    // creates a new one — so this handles both first-run and resume.
532→    const sessionDir = join(initConfig.sessionPath, '.pi-sessions');
533→    mkdirSync(sessionDir, { recursive: true });
534→
535→    if (initConfig.branchFromSessionPath) {
536→      // Branching: fork from the parent session's Pi session file.
537→      // Branches must not silently degrade to fresh sessions.
538→      const parentPiSessionDir = join(initConfig.branchFromSessionPath, '.pi-sessions');
539→      const parentPiSessionFile = findMostRecentSessionFile(parentPiSessionDir);
540→      if (!parentPiSessionFile) {
541→        throw new Error(`Pi branch preflight failed: no parent Pi session file found in ${parentPiSessionDir}`);
542→      }
543→
544→      debugLog(`Forking Pi session from parent: ${parentPiSessionFile}`);
545→      const forkedSessionManager = PiSessionManager.forkFrom(parentPiSessionFile, cwd, sessionDir);
546→
547→      // Strict branch cutoff: move leaf to the selected parent entry if provided.
548→      // This is Pi's equivalent of Claude resumeSessionAt.
549→      if (initConfig.branchFromSdkTurnId) {
550→        const anchorId = initConfig.branchFromSdkTurnId;
551→        const anchorEntry = forkedSessionManager.getEntry(anchorId);
552→        if (!anchorEntry) {
553→          throw new Error(`Pi branch preflight failed: branch anchor not found: ${anchorId}`);
554→        }
555→        forkedSessionManager.branch(anchorId);
556→        debugLog(`Applied Pi branch cutoff at entry: ${anchorId}`);
557→      }
558→
559→      sessionOptions.sessionManager = forkedSessionManager;
560→    } else {
561→      sessionOptions.sessionManager = PiSessionManager.continueRecent(cwd, sessionDir);
562→    }
563→
564→  }
565→
566→  // Set model if specified
567→  if (initConfig.model) {
568→    try {
569→      const piModel = resolvePiModel(modelRegistry, initConfig.model, initConfig.piAuth?.provider, shouldPreferCustomEndpoint());
570→      if (piModel) {
571→        // Verify resolved model's provider is compatible with the authenticated provider.
572→        // Without this, a model that resolves to a different provider (e.g. azure-openai-responses
573→        // when authed as github-copilot) would cause "No API key found" at runtime.
574→        const resolvedProvider = (piModel as any)?.provider;
575→        const isCompatible = !initConfig.piAuth ||
576→          resolvedProvider === initConfig.piAuth.provider ||
577→          resolvedProvider === 'custom-endpoint';
578→        if (isCompatible) {
579→          sessionOptions.model = piModel;
580→          setInterceptorApiHints(piModel as { api?: string; provider?: string; baseUrl?: string });
581→        } else {
582→          debugLog(`Model ${initConfig.model} resolved to incompatible provider ${resolvedProvider} (expected ${initConfig.piAuth!.provider}), skipping`);
583→          setInterceptorApiHints(undefined);
584→        }
585→      } else {
586→        setInterceptorApiHints(undefined);
587→      }
588→    } catch {
589→      debugLog(`Could not resolve Pi model: ${initConfig.model}`);
590→      setInterceptorApiHints(undefined);
591→    }
592→  } else {
593→    setInterceptorApiHints(undefined);
594→  }
595→
596→  // Set thinking level
597→  const piThinkingLevel = THINKING_TO_PI[initConfig.thinkingLevel as keyof typeof THINKING_TO_PI];
598→  if (piThinkingLevel) {
599→    sessionOptions.thinkingLevel = piThinkingLevel;
600→  }
601→
602→  // Create the session
603→  const { session } = await createAgentSession(sessionOptions);
604→  piSession = session;
605→
606→  // Pi SDK's createAgentSession ignores custom AgentTool objects passed via
607→  // `tools` — it only accepts its own internal Tool type and creates instances
608→  // internally. Inject our wrapped tools (with permission hooks) and proxy
609→  // tools via _baseToolsOverride, then rebuild the runtime so the session
610→  // actually uses them.
611→  const sessionInternal = piSession as any;
612→  if (typeof sessionInternal._buildRuntime !== 'function') {
613→    throw new Error(
614→      'Pi SDK internal API changed: _buildRuntime not found. ' +
615→      'Update ensureSession() for the new SDK version.',
616→    );
617→  }
618→
619→  const baseToolsOverride: Record<string, AgentTool<any>> = {};
620→  for (const tool of allTools) {
621→    baseToolsOverride[tool.name] = tool;
622→  }
623→  sessionInternal._baseToolsOverride = baseToolsOverride;
624→  sessionInternal._buildRuntime({
625→    activeToolNames: Object.keys(baseToolsOverride),
626→    includeAllExtensionTools: true,
627→  });
628→
629→  toolsChanged = false;
630→  debugLog(`Created Pi session: ${session.sessionId} (${Object.keys(baseToolsOverride).length} tools)`);
631→
632→  // Notify main process of session ID
633→  send({ type: 'session_id_update', sessionId: session.sessionId });
634→
635→  return session;
636→}
637→
638→
639→// ============================================================
640→// Tool Wrapping (Permission Enforcement + Large Response Summarization)
641→// ============================================================
642→
643→/**
644→ * Shared permission enforcement for both coding tools and proxy tools.
645→ * Checks mode-manager rules and, in Ask mode, prompts the user via the
646→ * pending-permissions handshake. Throws on deny or block.
647→ */
648→/**
649→ * Send pre_tool_use_request to main process and wait for response.
650→ * Returns the (potentially modified) input if approved, throws if blocked.
651→ * All permission checking, transforms, and source activation happen in the main process.
652→ */
653→async function requestPreToolUseApproval(
654→  sdkToolName: string,
655→  input: Record<string, unknown>,
656→  toolCallId?: string,
657→): Promise<Record<string, unknown>> {
658→  const requestId = `pi-ptu-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
659→
660→  send({
661→    type: 'pre_tool_use_request',
662→    requestId,
663→    toolName: sdkToolName,
664→    ...(toolCallId ? { toolCallId } : {}),
665→    input,
666→  });
667→
668→  const response = await new Promise<{ action: string; input?: Record<string, unknown>; reason?: string }>((resolve) => {
669→    pendingPreToolUse.set(requestId, { resolve });
670→  });
671→
672→  if (response.action === 'block') {
673→    throw new Error(response.reason || `Tool "${sdkToolName}" is not allowed`);
674→  }
675→
676→  return response.action === 'modify' && response.input ? response.input : input;
677→}
678→
679→function wrapToolsWithHooks(tools: AgentTool<any>[]): AgentTool<any>[] {
680→  return tools.map(tool => wrapSingleTool(tool));
681→}
682→
683→function makeErrorResult(message: string): AgentToolResult<any> {
684→  return {
685→    content: [{ type: 'text', text: message }],
686→    details: { isError: true },
687→  };
688→}
689→
690→function wrapSingleTool(tool: AgentTool<any>): AgentTool<any> {
691→  const originalExecute = tool.execute;
692→
693→  const wrappedExecute = async (
694→    toolCallId: string,
695→    params: any,
696→    signal?: AbortSignal,
697→    onUpdate?: (partialResult: AgentToolResult<any>) => void,
698→  ): Promise<AgentToolResult<any>> => {
699→    const sdkToolName = PI_TOOL_NAME_MAP[tool.name] || tool.name;
700→    let inputObj: Record<string, unknown> = { ...(params as Record<string, unknown>) };
701→
702→    // Extract intent before main process strips metadata (used for summarization)
703→    const intent = typeof inputObj._intent === 'string' ? inputObj._intent : undefined;
704→
705→    // Normalize Pi SDK parameter names: path → file_path
706→    if ((sdkToolName === 'Write' || sdkToolName === 'Edit' || sdkToolName === 'MultiEdit' || sdkToolName === 'NotebookEdit')
707→        && typeof inputObj.path === 'string' && !inputObj.file_path) {
708→      inputObj = { ...inputObj, file_path: inputObj.path };
709→    }
710→
711→    // Send to main process for permission checking + transforms
712→    inputObj = await requestPreToolUseApproval(sdkToolName, inputObj, toolCallId);
713→
714→    // Execute original tool with (potentially modified) input
715→    const result = await originalExecute(toolCallId, inputObj, signal, onUpdate);
716→
717→    // --- Post-execute: large response summarization ---
718→
719→    const resultText = result.content
720→      .filter((c): c is PiTextContent => c.type === 'text')
721→      .map(c => c.text)
722→      .join('');
723→
724→    if (estimateTokens(resultText) > TOKEN_LIMIT && initConfig) {
725→      try {
726→        const sessionPath = getSessionPath(
727→          initConfig.workspaceRootPath,
728→          initConfig.sessionId,
729→        );
730→
731→        const largeResult = await handleLargeResponse({
732→          text: resultText,
733→          sessionPath,
734→          context: {
735→            toolName: sdkToolName,
736→            input: inputObj,
737→            intent,
738→            userRequest: currentUserMessage,
739→          },
740→          summarize: runMiniCompletion,
741→        });
742→
743→        if (largeResult) {
744→          return {
745→            content: [{ type: 'text', text: largeResult.message }],
746→            details: result.details,
747→          };
748→        }
749→      } catch (error) {
750→        debugLog(
751→          `Large response handling failed: ${error instanceof Error ? error.message : String(error)}`,
752→        );
753→      }
754→    }
755→
756→    return result;
757→  };
758→
759→  return {
760→    ...tool,
761→    execute: wrappedExecute,
762→  };
763→}
764→
765→// ============================================================
766→// Proxy Tools (tools executed in main process)
767→// ============================================================
