776→      .replace(/_/g, ' ')
777→      .replace(/([a-z])([A-Z])/g, '$1 $2'),
778→    description: def.description,
779→    // Pi SDK omits tools without promptSnippet from the system prompt's
780→    // "Available tools" section, making them invisible to the LLM.
781→    // Derive a snippet from the description so proxy tools are listed.
782→    promptSnippet: def.description.length > 200
