790→      // Check speculative prefetch cache first (parallel call_llm optimization).
791→      // If this tool was prefetched on message_end, the request is already in-flight —
792→      // just await the result instead of sending a duplicate request.
793→      const prefetched = prefetchCache.get(toolCallId);
794→      if (prefetched) {
795→        prefetchCache.delete(toolCallId);
796→        debugLog(`Prefetch cache hit for ${def.name} (toolCallId: ${toolCallId})`);
797→        const result = await prefetched;
798→        return {
799→          content: [{ type: 'text', text: result.content }],
800→          details: result.isError ? { isError: true } : undefined,
801→        };
802→      }
803→
804→      const inputObj = params as Record<string, unknown>;
805→
806→      // Permission checking via main process
807→      const approvedInput = await requestPreToolUseApproval(def.name, inputObj, toolCallId);
808→
809→      // Execute via main process
810→      const requestId = `proxy-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
811→
812→      send({
813→        type: 'tool_execute_request',
814→        requestId,
815→        toolName: def.name,
816→        args: approvedInput,
817→      });
818→
819→      const result = await new Promise<{ content: string; isError: boolean }>((resolve) => {
820→        pendingToolExecutions.set(requestId, { resolve });
821→      });
822→
823→      return {
824→        content: [{ type: 'text', text: result.content }],
825→        details: result.isError ? { isError: true } : undefined,
826→      };
827→    },
828→  }));
