 6→/**
 7→ * Resolve a Pi SDK model from the registry, with optional custom-endpoint precedence.
 8→ *
 9→ * Resolution order:
10→ * 1. If `preferCustomEndpoint` is true, try `'custom-endpoint'` provider first
11→ * 2. Exact provider+model lookup via `piAuthProvider`
12→ * 3. Full `getAll()` scan by id/name
13→ * 4. Common provider fallback list (includes 'custom-endpoint')
14→ */
15→export function resolvePiModel(
16→  modelRegistry: PiModelRegistry,
17→  modelId: string,
18→  piAuthProvider?: string,
19→  preferCustomEndpoint?: boolean,
20→): PiModel | undefined {
21→  // Strip Craft's pi/ prefix — Pi SDK uses bare model IDs (e.g. "claude-sonnet-4-6")
22→  const bareId = modelId.startsWith('pi/') ? modelId.slice(3) : modelId;
23→
24→  // Custom-endpoint takes precedence when configured
25→  if (preferCustomEndpoint) {
26→    const custom = modelRegistry.find('custom-endpoint', bareId);
27→    if (custom) return custom;
28→  }
29→
30→  // If we know the auth provider, do an exact provider+model lookup first.
31→  // This avoids the getAll() ambiguity where the same model ID exists under
32→  // multiple providers (e.g., "gpt-5.2" under both "openai" and
33→  // "azure-openai-responses") and the wrong one matches first.
34→  if (piAuthProvider) {
35→    const exact = modelRegistry.find(piAuthProvider, bareId);
36→    if (exact) {
37→      // MiniMax CN API rejects model IDs with the 'MiniMax-' prefix (e.g. 500 for
38→      // 'MiniMax-M2.5-highspeed') but accepts bare names ('M2.5-highspeed').
39→      if (piAuthProvider === 'minimax-cn' && exact.id.startsWith('MiniMax-')) {
40→        return { ...exact, id: exact.id.slice('MiniMax-'.length) };
41→      }
42→      return exact;
43→    }
44→  }
45→
46→  // Fallback: search all available models.
47→  // When piAuthProvider is set, only return models from the same provider
48→  // (or 'custom-endpoint'). Without this guard, a model that exists under
49→  // a different provider (e.g. "gpt-5.4" under "azure-openai-responses"
50→  // when authed as "github-copilot") would be returned, and the Pi SDK
51→  // would fail with "No API key found for <wrong-provider>".
52→  const allModels = modelRegistry.getAll();
53→  const match = allModels.find(m =>
54→    (m.id === bareId || m.name === bareId) &&
55→    (!piAuthProvider || (m as any).provider === piAuthProvider || (m as any).provider === 'custom-endpoint'),
56→  );
57→  if (match) return match;
58→
59→  // Try common providers with the model ID
60→  const providers = ['custom-endpoint', 'anthropic', 'openai', 'google'];
61→  for (const provider of providers) {
62→    // Skip providers incompatible with the authenticated provider
63→    if (piAuthProvider && provider !== piAuthProvider && provider !== 'custom-endpoint') continue;
64→    const model = modelRegistry.find(provider, bareId);
65→    if (model) return model;
66→  }
67→
68→  return undefined;
69→}
